const proximoQueueItemPendente = `-- name: ProximoQueueItemPendente :one
SELECT id, kind, ref_id, trigger, status, progress_current, progress_total,
    message, enqueued_at, started_at, finished_at,
    step_index, step_total, step_label, current_item, progress_ok, progress_failed
FROM queue_item
WHERE status = 'queued'
ORDER BY enqueued_at, id
LIMIT 1
`

// The worker uses this to find the oldest 'queued' item (FIFO by
// enqueued_at; id as a stable tiebreaker when enqueued_at collides).
// sql.ErrNoRows = empty queue, the worker sleeps for a short interval.
func (q *Queries) ProximoQueueItemPendente(ctx context.Context) (QueueItem, error) {
	row := q.db.QueryRowContext(ctx, proximoQueueItemPendente)
	var i QueueItem
	err := row.Scan(
		&i.ID,
		&i.Kind,
		&i.RefID,
		&i.Trigger,
		&i.Status,
		&i.ProgressCurrent,
		&i.ProgressTotal,
		&i.Message,
		&i.EnqueuedAt,
		&i.StartedAt,
		&i.FinishedAt,
		&i.StepIndex,
		&i.StepTotal,
		&i.StepLabel,
		&i.CurrentItem,
		&i.ProgressOk,
		&i.ProgressFailed,
	)
	return i, err
}
